#!/usr/bin/env python3
import re, sys
from collections import defaultdict
cur_obj=None; x=y=z=0.0
line_re=re.compile(r'^(G0|G1)\b(.*)')
def pp(rest):
    d={}
    for m in re.finditer(r'([XYZEFS])([-+]?\d*\.?\d+)',rest): d[m.group(1)]=float(m.group(2))
    return d
layers=defaultdict(list)
with open('/app/text.gcode') as f:
    for line in f:
        s=line.strip()
        if not s: continue
        if s.startswith('M486'):
            for t in s.split()[1:]:
                if t.startswith('S'):
                    v=int(float(t[1:])); cur_obj=None if v<0 else v
            continue
        if not (s.startswith('G0') or s.startswith('G1')): continue
        m=line_re.match(s)
        if not m: continue
        p=pp(m.group(2))
        nx=p.get('X',x); ny=p.get('Y',y); nz=p.get('Z',z); e=p.get('E')
        if (('X' in p or 'Y' in p) and e is not None and e>0) and cur_obj==0:
            layers[round(z,3)].append((x,y,nx,ny))
        if 'Z' in p: z=nz
        x=nx; y=ny

def render_layer(zz, cols=100):
    segs=layers[zz]
    xs=[c for s in segs for c in (s[0],s[2])]
    ys=[c for s in segs for c in (s[1],s[3])]
    minx,maxx=min(xs),max(xs); miny,maxy=min(ys),max(ys)
    mpc=(maxx-minx)/cols
    rows=max(int((maxy-miny)/(mpc*2.0)),3)
    grid=[[' ']*cols for _ in range(rows)]
    for (x0,y0,x1,y1) in segs:
        def cp(xx): return (xx-minx)/mpc
        def rp(yy): return (maxy-yy)/(mpc*2.0)
        steps=max(int(max(abs(cp(x1)-cp(x0)),abs(rp(y1)-rp(y0)))*3)),1)
        for i in range(steps+1):
            t=i/steps if steps else 0
            xx=x0+(x1-x0)*t; yy=y0+(y1-y0)*t
            c=int(round(cp(xx))); r=int(round(rp(yy)))
            if 0<=r<rows and 0<=c<cols: grid[r][c]='#'
    print(f"\n=== layer z={zz}  segs={len(segs)}  X[{minx:.1f},{maxx:.1f}] Y[{miny:.1f},{maxy:.1f}] ===")
    for row in grid: print(''.join(row))

for zz in [0.48, 2.72, 8.04, 20.0, 35.0, 50.0]:
    if zz in layers: render_layer(zz)

